#include <bits/stdc++.h>
using namespace std;
class Solution {public:vector<int> successfulPairs(vector<int>& spells,vector<int>& potions,long long success){sort(potions.begin(),potions.end());vector<int> ans;for(long long s:spells){long long need=(success+s-1)/s;ans.push_back(potions.end()-lower_bound(potions.begin(),potions.end(),need));}return ans;}};
